// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface ICall{function ping() external;} contract ReentrantVault { mapping(address=>uint) public balance; function deposit() external payable { balance[msg.sender]+=msg.value; } function withdraw() external { uint a=balance[msg.sender]; (bool ok,)=msg.sender.call{value:a}(""); require(ok); balance[msg.sender]=0; }}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract GuardedVault { mapping(address=>uint) public balance; bool private locked; modifier nonReentrant(){require(!locked);locked=true;_;locked=false;} function deposit() external payable {balance[msg.sender]+=msg.value;} function withdraw() external nonReentrant {uint a=balance[msg.sender];balance[msg.sender]=0;(bool ok,)=msg.sender.call{value:a}("");require(ok);} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract TxOriginAdmin { address public owner; constructor(){owner=msg.sender;} function sweep(address payable to) external {require(tx.origin==owner);to.transfer(address(this).balance);} receive() external payable{} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract SenderAdmin { address public immutable owner; constructor(){owner=msg.sender;} function sweep(address payable to) external {require(msg.sender==owner);to.transfer(address(this).balance);} receive() external payable{} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract UninitializedOwner { address public owner; function initialize(address a) external {owner=a;} function mint() external view {require(msg.sender==owner);} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract OneTimeInitializer {address public owner; bool public initialized; function initialize(address a) external {require(!initialized);initialized=true;owner=a;} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract UncheckedCall {function forward(address target, bytes calldata data) external {target.call(data);} }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract CheckedCall {function forward(address target, bytes calldata data) external { (bool ok, bytes memory ret)=target.call(data); require(ok,string(ret)); } }

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract DelegateUserTarget {function run(address target, bytes calldata data) external { (bool ok,)=target.delegatecall(data); require(ok); }}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract DelegateAllowlist {mapping(address=>bool) public allowed; address public owner; constructor(){owner=msg.sender;} function set(address a,bool v) external {require(msg.sender==owner);allowed[a]=v;} function run(address target,bytes calldata data) external {require(allowed[target]);(bool ok,)=target.delegatecall(data);require(ok);} }
